package main
import("context";"fmt";"os";"path/filepath";"reflect";"github.com/system-inc/adamic/internal/load";"github.com/system-inc/adamic/internal/lower";"github.com/system-inc/adamic/internal/ir")
func visit(v reflect.Value){if !v.IsValid(){return};if v.Kind()==reflect.Interface||v.Kind()==reflect.Pointer {if !v.IsNil(){visit(v.Elem())};return};if v.CanInterface(){if a,ok:=v.Interface().(ir.TypedArrayNew);ok{fmt.Printf("TypedArrayNew Of=%v FromArray=%v Source=%T\n",a.Of,a.FromArray,a.Source)}};switch v.Kind(){case reflect.Struct:for i:=0;i<v.NumField();i++{visit(v.Field(i))};case reflect.Slice:for i:=0;i<v.Len();i++{visit(v.Index(i))}}}
func main(){dir,e:=os.MkdirTemp("","u044-witness");if e!=nil{panic(e)};defer os.RemoveAll(dir);source:=`const a = new Uint8Array([]); const b = new Uint8Array([1,2]);`;if len(os.Args)>1 {source=os.Args[1]};p:=filepath.Join(dir,"main.a");if e=os.WriteFile(p,[]byte(source),0600);e!=nil{panic(e)};loaded,e:=load.Load([]string{p});if e!=nil{panic(e)};program,e:=lower.Lower(context.Background(),loaded);fmt.Printf("error=%v\n",e);if program!=nil{visit(reflect.ValueOf(program.Main))}}
